use ImAuthenticator\Security;use ImAuthenticator\Web;$s=require dirname(__DIR__).'/src/bootstrap.php';extract($s,EXTR_SKIP);$user=$auth->requireUser();$message='';if(strtoupper($_SERVER['REQUEST_METHOD']??'GET')==='POST'){if(!(bool)$user['is_admin']){http_response_code(403);exit('Brak uprawnień.');}Security::requireCsrf($_POST['_csrf']??null);try{$id=$organizations->create((string)($_POST['name']??''),(string)($_POST['slug']??''),(int)$user['id']);Web::redirect('/admin/organizations/'.$id);}catch(Throwable$e){$message='<div class="alert danger">'.Web::e($e->getMessage()).'</div>';}}$rows='';$orgs=(bool)$user['is_admin']?$db->all('SELECT * FROM organizations ORDER BY name'):$db->all("SELECT o.* FROM organizations o JOIN organization_memberships om ON om.organization_id=o.id WHERE om.user_id=? AND om.role IN ('owner','admin') AND om.status='active' ORDER BY o.name",[(int)$user['id']]);foreach($orgs as$o){$members=$db->one("SELECT COUNT(*) AS c FROM organization_memberships WHERE organization_id=? AND status='active'",[(int)$o['id']]);$apps=$db->one('SELECT COUNT(*) AS c FROM applications WHERE organization_id=? AND deleted_at IS NULL',[(int)$o['id']]);$rows.='<tr><td><a href="/admin/organizations/'.(int)$o['id'].'"><strong>'.Web::e($o['name']).'</strong></a></td><td>'.Web::e($o['slug']).'</td><td>'.Web::e($o['status']).'</td><td>'.(int)$members['c'].'</td><td>'.(int)$apps['c'].'</td></tr>';}if($rows==='')$rows='<tr><td colspan="5" class="empty">Brak organizacji, którymi możesz zarządzać.</td></tr>';$create=(bool)$user['is_admin']?'<section class="card"><h2>Nowa organizacja</h2><form method="post"><input type="hidden" name="_csrf" value="'.Web::e(Security::csrfToken()).'"><label>Nazwa<input name="name" required></label><label>Slug<input name="slug"></label><button class="primary">Utwórz</button></form></section>':'';$content='<div class="page-head"><div><h1>Organizations / Tenants</h1><p>Izolacja członkostw, aplikacji i administratorów organizacji.</p></div></div>'.$message.$create.'<div class="table-wrap"><table><thead><tr><th>Nazwa</th><th>Slug</th><th>Status</th><th>Użytkownicy</th><th>Aplikacje</th></tr></thead><tbody>'.$rows.'</tbody></table></div>';Web::page('Organizacje',$content,$user);
